using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Collections.Generic;
public sealed class LaunchMode {public string homePreset="",homeProject="";public List<HomeBlock> homeLayout;public string id="",name="",description="",pageKind="",pageId="";public List<ModeAction> actions=new List<ModeAction>();}
public sealed class ModeAction {public string kind="",label="",target="";}
internal sealed class ModeLaunchSession {
 internal readonly LaunchMode Mode;internal int Index,Opened;internal readonly List<string> Errors=new List<string>();internal bool Cancelled;
 internal ModeLaunchSession(LaunchMode mode){Mode=LaunchModes.Clone(mode);}
 internal bool Step(Action<ModeAction> executor){if(Cancelled||Index>=Mode.actions.Count)return true;var action=Mode.actions[Index++];try{executor(action);Opened++;}catch(Exception ex){Errors.Add(action.label+" : "+ex.Message);}return Index>=Mode.actions.Count;}
}
internal static class LaunchModes {
 internal static LaunchMode Clone(LaunchMode mode){return new LaunchMode{homePreset=mode.homePreset,homeProject=mode.homeProject,homeLayout=DayDashboard.CloneLayout(mode.homeLayout),id=mode.id,name=mode.name,description=mode.description,pageKind=mode.pageKind,pageId=mode.pageId,actions=mode.actions.Select(a=>new ModeAction{kind=a.kind,label=a.label,target=a.target}).ToList()};}
 internal static string KindName(string kind){return kind=="exe"?"Application":kind=="folder"?"Dossier":kind=="url"?"Site web":kind=="discord"?"Discord":"Spotify";}
 internal static void Validate(Data d){if(d.modes==null)d.modes=new List<LaunchMode>();if(d.modes.Count>100)throw new InvalidDataException("Limite : 100 modes personnalisés.");var ids=new HashSet<string>();foreach(var mode in d.modes){if(mode==null||String.IsNullOrWhiteSpace(mode.name)||mode.name.Length>60||(mode.description??"").Length>500)throw new InvalidDataException("Mode personnalisé invalide.");if(String.IsNullOrEmpty(mode.id)||!ids.Add(mode.id)){mode.id=Guid.NewGuid().ToString();ids.Add(mode.id);}mode.description=mode.description??"";mode.pageKind=mode.pageKind??"";mode.pageId=mode.pageId??"";if(!new[]{"","project","note"}.Contains(mode.pageKind)||(mode.pageKind!=""&&String.IsNullOrWhiteSpace(mode.pageId))||mode.pageId.Length>200)throw new InvalidDataException("Page de destination invalide.");if(mode.actions==null)mode.actions=new List<ModeAction>();if(mode.actions.Count>20)throw new InvalidDataException("Limite : 20 ouvertures par mode.");foreach(var action in mode.actions)ValidateAction(action);}}
 internal static void ValidateAction(ModeAction action){if(action==null||!new[]{"exe","folder","url","discord","spotify"}.Contains(action.kind)||String.IsNullOrWhiteSpace(action.label)||action.label.Length>200||(action.target??"").Length>2048)throw new InvalidDataException("Action de mode invalide.");action.target=action.target??"";if(action.kind=="exe"||action.kind=="folder"){if(!Path.IsPathRooted(action.target)||action.target.IndexOfAny(new[]{'\r','\n','\0'})>=0)throw new InvalidDataException("Choisissez un chemin absolu.");if(action.kind=="exe"&&!String.Equals(Path.GetExtension(action.target),".exe",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Choisissez une application .exe.");}if(action.kind=="url"){Uri uri;if(!Uri.TryCreate(action.target,UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https"))throw new InvalidDataException("Utilisez une adresse http ou https.");}}
 internal static ProcessStartInfo Prepare(ModeAction action){ValidateAction(action);if(action.kind=="exe"){if(!File.Exists(action.target))throw new FileNotFoundException("Application introuvable sur ce PC.");return new ProcessStartInfo(action.target){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(action.target)};}if(action.kind=="folder"){if(!Directory.Exists(action.target))throw new DirectoryNotFoundException("Dossier introuvable sur ce PC.");return new ProcessStartInfo(action.target){UseShellExecute=true};}if(action.kind=="url")return new ProcessStartInfo(action.target){UseShellExecute=true};throw new InvalidOperationException("Cette application utilise son ouverture dédiée.");}
 internal static void Execute(ModeAction action){ValidateAction(action);if(action.kind=="discord"){if(!AppLinks.TryDiscord())throw new InvalidOperationException("Discord n’est pas installé ou son ouverture a échoué.");return;}if(action.kind=="spotify"){using(var key=Microsoft.Win32.Registry.ClassesRoot.OpenSubKey(@"spotify\shell\open\command")){if(key==null)throw new InvalidOperationException("Spotify n’est pas installé ou associé sur ce PC.");}Process.Start(new ProcessStartInfo("spotify:"){UseShellExecute=true});return;}if(action.kind=="url"){AppLinks.Open(action.target);return;}Process.Start(Prepare(action));}
 internal static void Test(string folder){var d=new Data();var mode=new LaunchMode{id="test-mode",name="Travail",pageKind="project",pageId="Travail",actions=new List<ModeAction>{new ModeAction{kind="folder",label="Dossier",target=Path.GetFullPath(folder)},new ModeAction{kind="url",label="Documentation",target="https://example.com"},new ModeAction{kind="discord",label="Discord"}}};d.modes.Add(mode);Store.Validate(d);if(GlobalSearch.Find(d,"travail","mode").Count!=1)throw new Exception("Recherche mode");d.favorites.Add(new Favorite{kind="mode",id=mode.id,label=mode.name});Store.Validate(d);if(GlobalSearch.Resolve(d,d.favorites[0]).Title!="Travail")throw new Exception("Favori mode");var session=new ModeLaunchSession(mode);mode.actions[0].label="Modifié";var calls=new List<string>();while(!session.Step(a=>{calls.Add(a.label);if(a.kind=="url")throw new IOException("Test indisponible");})){}if(calls.Count!=3||calls[0]!="Dossier"||session.Opened!=2||session.Errors.Count!=1)throw new Exception("Ordre / isolation / erreurs de mode");session.Step(a=>{throw new Exception("Relance inattendue");});if(calls.Count!=3)throw new Exception("Relance du mode");var cancelled=new ModeLaunchSession(mode);cancelled.Cancelled=true;cancelled.Step(a=>{throw new Exception("Mode annulé exécuté");});if(cancelled.Index!=0)throw new Exception("Annulation du mode");bool bad=false;try{ValidateAction(new ModeAction{kind="url",label="Interdit",target="javascript:alert(1)"});}catch(InvalidDataException){bad=true;}if(!bad)throw new Exception("Protocole interdit accepté");bad=false;try{ValidateAction(new ModeAction{kind="exe",label="Script",target=Path.Combine(Path.GetFullPath(folder),"script.ps1")});}catch(InvalidDataException){bad=true;}if(!bad)throw new Exception("Script accepté comme application");var info=Prepare(mode.actions[0]);if(!info.UseShellExecute||info.Arguments.Length>0)throw new Exception("Préparation dossier incorrecte");var store=new Store(Path.Combine(folder,"modes"));store.Value=d;store.Save();store=new Store(store.Root);if(store.Value.modes[0].actions.Count!=3)throw new Exception("Persistance modes");store.Export(Path.Combine(folder,"modes-export.json"));store.Value.modes.Clear();store.Import(Path.Combine(folder,"modes-export.json"));if(store.Value.modes.Count!=1)throw new Exception("Import modes");}
}
